 Map<String,Object> finalReadiness(JdbcMinutesFactsReader.Snapshot snapshot,PublicationGraph.Plan publication){
  require(snapshot.graph().discovery().meeting().equals(publication.meeting()),PROVENANCE_UNAVAILABLE);var existing=snapshot.graph().auxiliary().getOrDefault("publication",List.of());
  if(existing.isEmpty())return readiness(snapshot,true);if(existing.size()!=1||!"FAILED".equals(existing.getFirst().get("state")))return readiness(snapshot,true);
  String id=(String)existing.getFirst().get("id");try{PublicationLocalDecision.requireClosed(publication,id);}catch(Failure denied){if(denied.code()==BUDGET_EXCEEDED||denied.code()==CANCELLED)throw denied;return readiness(snapshot,true);}
  return readiness(snapshot,true,id);
 }
