 private Map<String,Object> coverage(JdbcMinutesFactsReader.Snapshot snapshot,FullRow target,ReviewKind kind){var facts=snapshot.facts();String id=target.string("id");
  // A new immutable element has no review credit. There is no hash to compare until an
  // exact target/kind review exists; all retained reviews were already verified during acquisition.
  if(!hasReviewFor(rows(snapshot,Table.RESULT_REVIEW),id,kind))return map("targetKind","ELEMENT","targetId",id,"reviewKind",kind.name(),"scope",kind==ReviewKind.SOURCE_SUPPORT?"WHOLE":null,"reviewId",null,"outcome",null,"satisfied",false);
  Anchor anchor=kind==ReviewKind.ACTION_FIELDS?null:OutputValidation.anchor(target.string("body"),0,OutputValidation.scalarCount(target.string("body"),()->false),()->false);var evidence=rows(snapshot,Table.EVIDENCE_LINK).stream().filter(row->id.equals(row.nullableString("element_id"))).map(row->row.string("id")).sorted().toList();var scope=new ReviewFacts(snapshot.graph().discovery().meeting(),kind,id,null,anchor,evidence,facts);var profiles=facts.configurations().stream().map(c->c.profiles().definition(ProfileKind.REVIEW_HASH)).distinct().toList();require(profiles.size()==1,PROFILE_UNAVAILABLE);var profile=profiles.getFirst();// Snapshot construction already verified every stored review's exact target, scope,
  // evidence membership and original raw source-chain hashes. Reuse only an identical
  // immutable whole scope; the final graph/authority capture still follows this projection.
  var verified=matchingValidatedReview(scope,profile.version());
  if(verified.isEmpty())return map("targetKind","ELEMENT","targetId",id,"reviewKind",kind.name(),"scope",kind==ReviewKind.SOURCE_SUPPORT?"WHOLE":null,"reviewId",null,"outcome",null,"satisfied",false);
  String th=verified.get().string("target_hash"),sh=verified.get().string("source_set_hash");var credit=new ReviewCoverageEvaluator().evaluate(scope,th,sh,rows(snapshot,Table.RESULT_REVIEW),()->false);boolean meetingEvidence=rows(snapshot,Table.EVIDENCE_LINK).stream().filter(row->evidence.contains(row.string("id"))).anyMatch(row->"TRANSCRIPT".equals(one(snapshot,Table.SOURCE_LOCATOR,row.string("locator_id")).string("kind")));boolean satisfied=kind==ReviewKind.ACTION_FIELDS?"CONFIRMED".equals(credit.outcome()):credit.wholeTargetSupported()&&!evidence.isEmpty()&&meetingEvidence;return map("targetKind","ELEMENT","targetId",id,"reviewKind",kind.name(),"scope",kind==ReviewKind.SOURCE_SUPPORT?"WHOLE":null,"reviewId",credit.reviewId(),"outcome",credit.outcome(),"satisfied",satisfied);}
 static Optional<FullRow> matchingValidatedReview(ReviewFacts scope,String profile){
  String anchor=scope.anchor()==null?null:OutputValidation.anchorText(scope.anchor());var evidence=new TreeSet<>(scope.selectedEvidenceIds());
  return scope.stored().rows().stream().filter(row->row.table()==Table.RESULT_REVIEW&&scope.meetingId().equals(row.string("meeting_id"))&&scope.kind().name().equals(row.string("review_kind"))&&Objects.equals(scope.elementId(),row.nullableString("element_id"))&&Objects.equals(scope.minutesRevisionId(),row.nullableString("minutes_revision_id"))&&Objects.equals(anchor,row.nullableString("target_anchor"))&&profile.equals(row.string("hash_profile")))
   .filter(row->new TreeSet<>(scope.stored().rows().stream().filter(member->member.table()==Table.RESULT_REVIEW_EVIDENCE&&row.string("id").equals(member.string("review_id"))).map(member->member.string("evidence_id")).toList()).equals(evidence))
   .max(Comparator.comparingLong(row->row.number("review_no")));
 }
 static boolean hasReviewFor(List<FullRow> reviews,String element,ReviewKind kind){return reviews.stream().anyMatch(row->element.equals(row.nullableString("element_id"))&&kind.name().equals(row.string("review_kind")));}
 private static List<Object> physicalExclusion(JdbcMinutesFactsReader.Snapshot snapshot,String locator,String category){var row=one(snapshot,Table.SOURCE_LOCATOR,locator);var value=new ArrayList<Object>();value.add(category);for(var column:Table.SOURCE_LOCATOR.columns())if(!Set.of("id","meeting_id").contains(column.name()))value.add(row.value(column.name()));return List.copyOf(value);}
 private static List<FullRow> effectiveEvidence(JdbcMinutesFactsReader.Snapshot snapshot,String body,String set){var values=new TreeMap<String,FullRow>();if(body!=null)for(var row:targetEvidence(snapshot,"BODY",body))values.put(row.string("id"),row);if(set!=null)for(var row:targetEvidence(snapshot,"SET",set))values.put(row.string("id"),row);return List.copyOf(values.values());}
 private static Set<String> directoryLocators(JdbcMinutesFactsReader.Snapshot snapshot,String set){var ids=new HashSet<String>();for(boolean sensitive:List.of(true,false)){var parents=rows(snapshot,sensitive?Table.SENSITIVE_DETECTION:Table.BACKGROUND_NOTE).stream().filter(row->set!=null&&set.equals(row.string("set_id"))).map(row->row.string("id")).toList();for(var member:rows(snapshot,sensitive?Table.SENSITIVE_DETECTION_SOURCE:Table.BACKGROUND_NOTE_SOURCE))if(parents.contains(member.string(sensitive?"detection_id":"note_id")))ids.add(member.string("locator_id"));}for(var row:rows(snapshot,Table.SENSITIVE_EXCLUSION))if(Objects.equals(snapshot.observation().get("exclusion_revision_id"),row.string("revision_id")))ids.add(row.string("locator_id"));return Set.copyOf(ids);}
 static List<Map<String,Object>> directories(JdbcMinutesFactsReader.Snapshot snapshot,String set,boolean sensitive){var result=new ArrayList<Map<String,Object>>();for(var row:rows(snapshot,sensitive?Table.SENSITIVE_DETECTION:Table.BACKGROUND_NOTE).stream().filter(value->set!=null&&set.equals(value.string("set_id"))).sorted(Comparator.comparing((FullRow value)->sensitive?value.string("category"):"").thenComparingLong(value->value.number("ordinal")).thenComparing(value->value.string("id"))).toList()){var locators=rows(snapshot,sensitive?Table.SENSITIVE_DETECTION_SOURCE:Table.BACKGROUND_NOTE_SOURCE).stream().filter(value->row.string("id").equals(value.string(sensitive?"detection_id":"note_id"))).map(value->value.string("locator_id")).sorted().toList();var value=new LinkedHashMap<String,Object>();value.put("id",row.string("id"));value.put("ordinalToken",Long.toString(row.number("ordinal")));value.put(sensitive?"category":"body",row.string(sensitive?"category":"body"));value.put("locatorIds",locators);result.add(Collections.unmodifiableMap(value));}if(sensitive)for(var item:rows(snapshot,Table.SENSITIVE_EXCLUSION))if(Objects.equals(snapshot.observation().get("exclusion_revision_id"),item.string("revision_id"))&&result.stream().noneMatch(d->d.get("category").equals(item.string("category"))&&((List<?>)d.get("locatorIds")).contains(item.string("locator_id"))))result.add(map("id",item.string("locator_id"),"ordinalToken",Long.toString(result.size()+1L),"category",item.string("category"),"locatorIds",List.of(item.string("locator_id"))));return List.copyOf(result);}
 private static List<FullRow> targetEvidence(JdbcMinutesFactsReader.Snapshot s,String kind,String id){var elements=kind.equals("SET")?rows(s,Table.MINUTES_ELEMENT).stream().filter(r->id.equals(r.string("set_id"))).map(r->r.string("id")).toList():List.of();return rows(s,Table.EVIDENCE_LINK).stream().filter(r->kind.equals("BODY")?id.equals(r.nullableString("minutes_revision_id")):kind.equals("ELEMENT")?id.equals(r.nullableString("element_id")):elements.contains(r.nullableString("element_id"))).toList();}
 private static Map<String,Object> elements(JdbcMinutesFactsReader.Snapshot snapshot,String set,boolean owner){var result=new LinkedHashMap<String,Object>();for(Category category:Category.values()){var items=new ArrayList<Object>();for(var row:rows(snapshot,Table.MINUTES_ELEMENT).stream().filter(r->set!=null&&set.equals(r.string("set_id"))&&category.name().equals(r.string("category"))).sorted(Comparator.comparingLong(r->r.number("ordinal"))).toList()){var accepted=rows(snapshot,Table.ACTION_ITEM).stream().filter(r->row.string("id").equals(r.string("element_id"))).map(JdbcMinutesSavedQueries::project).toList();var suggestion=owner?rows(snapshot,Table.ACTION_SUGGESTION).stream().filter(r->row.string("id").equals(r.string("element_id"))).map(JdbcMinutesSavedQueries::project).toList():List.of();items.add(map("id",row.string("id"),"body",row.string("body"),"ordinalToken",Long.toString(row.number("ordinal")),"action",accepted.isEmpty()?null:accepted.getFirst(),"suggestion",suggestion.isEmpty()?null:suggestion.getFirst()));}result.put(category.name(),items);}return Collections.unmodifiableMap(result);}
 private static Map<String,Object> bodyProjection(FullRow row,boolean owner){var value=new LinkedHashMap<String,Object>();value.put("id",row.string("id"));value.put("title",row.string("title"));value.put("body",row.string("body"));value.put("titleOrigin",row.string("title_origin"));value.put("revisionToken",Long.toString(row.number("revision")));if(owner){value.put("generationInputId",row.nullableString("generation_input_id"));value.put("parentId",row.nullableString("parent_id"));}return Collections.unmodifiableMap(value);}
 private static void saved(JdbcMinutesFactsReader.Snapshot s,String id,boolean body){if(s.graph().auxiliary().getOrDefault("generation_candidate",List.of()).stream().anyMatch(r->id.equals(r.get(body?"minutes_revision_id":"element_set_id"))))throw absent();}
 private static ama.contract.TranscriptContracts.Failure absent(){return new ama.contract.TranscriptContracts.Failure(404,"SAVED_TARGET_NOT_FOUND");}
 private static List<FullRow> rows(JdbcMinutesFactsReader.Snapshot s,Table table){return s.facts().rows().stream().filter(r->r.table()==table).toList();}private static FullRow one(JdbcMinutesFactsReader.Snapshot s,Table table,String id){return JdbcMinutesFactsReader.one(s.graph(),table,id);}
 static long counter(String value){if(value==null||!value.matches("0|[1-9][0-9]*"))throw new IllegalArgumentException("Canonical counter required");try{long n=Long.parseLong(value);if(n<0||n>Long.MAX_VALUE-1)throw new IllegalArgumentException("Counter out of range");return n;}catch(NumberFormatException e){throw new IllegalArgumentException("Counter out of range");}}
 static Map<String,Object> project(FullRow row){var result=new LinkedHashMap<String,Object>();for(var column:row.table().columns()){var value=row.value(column.name());result.put(column.kind()==CellKind.UINT?column.name()+"Token":column.name(),value instanceof NullCell?null:value instanceof UIntCell n?Long.toString(n.value()):((TextCell)value).value());}return Collections.unmodifiableMap(result);}
 private Map<String,Object> presentation(JdbcMinutesFactsReader.Snapshot snapshot,String body,String set,boolean owner){
  var root=snapshot.observation();var revision=body==null?null:one(snapshot,Table.MINUTES_REVISION,body);var input=revision==null||revision.nullableString("generation_input_id")==null?null:one(snapshot,Table.GENERATION_INPUT,revision.string("generation_input_id"));
  String selected=(String)root.get("template_revision_id"),applied=input==null?null:input.string("template_revision_id"),exclusion=(String)root.get("exclusion_revision_id"),appliedExclusion=input==null?null:input.string("exclusion_revision_id");
  var markers=new ArrayList<Map<String,Object>>();for(var directory:directories(snapshot,set,true))for(Object locator:(List<?>)directory.get("locatorIds")){var physical=physicalExclusion(snapshot,(String)locator,(String)directory.get("category"));boolean chosen=rows(snapshot,Table.SENSITIVE_EXCLUSION).stream().anyMatch(r->Objects.equals(exclusion,r.string("revision_id"))&&physical.equals(physicalExclusion(snapshot,r.string("locator_id"),r.string("category"))));boolean used=rows(snapshot,Table.SENSITIVE_EXCLUSION).stream().anyMatch(r->Objects.equals(appliedExclusion,r.string("revision_id"))&&physical.equals(physicalExclusion(snapshot,r.string("locator_id"),r.string("category"))));markers.add(map("locatorId",locator,"category",directory.get("category"),"selected",chosen,"applied",used));}
  var states=new ArrayList<Map<String,Object>>();for(var element:rows(snapshot,Table.MINUTES_ELEMENT))if(Objects.equals(set,element.string("set_id"))&&Set.of("CONCLUSION","ACTION").contains(element.string("category"))){var support=coverage(snapshot,element,ReviewKind.SOURCE_SUPPORT);var action=element.string("category").equals("ACTION")?coverage(snapshot,element,ReviewKind.ACTION_FIELDS):null;states.add(map("elementId",element.string("id"),"sourceSupported",support.get("satisfied"),"actionFieldsConfirmed",action==null?null:action.get("satisfied")));}
  String by=revision==null?null:revision.string("created_by");if(by!=null){var names=j.queryForList("SELECT display_name FROM enterprise_identity WHERE enterprise_id=? LIMIT 1",String.class,by);if(!names.isEmpty())by=names.getFirst();}
  return map("modifiedBy",by,"modifiedAt",revision==null?null:revision.string("created_at"),"appliedTemplateName",templateName(snapshot,applied),"selectedTemplateName",owner?templateName(snapshot,selected):null,"exclusions",markers,"reviewStates",states,"sensitiveConflict",sensitiveConflict(snapshot,body,set));
 }
 private static String templateName(JdbcMinutesFactsReader.Snapshot snapshot,String id){if(id==null)return null;String name=one(snapshot,Table.TEMPLATE_REVISION,id).string("name");return name.equals("Controlled minutes")?"AI生成":name;}
 private static boolean sensitiveConflict(JdbcMinutesFactsReader.Snapshot snapshot,String body,String set){
  var excluded=new ArrayList<String>();var content=new ArrayList<String>();if(body!=null){var revision=one(snapshot,Table.MINUTES_REVISION,body);content.add(revision.string("title"));content.add(revision.string("body"));}for(var row:rows(snapshot,Table.MINUTES_ELEMENT))if(Objects.equals(set,row.string("set_id")))content.add(row.string("body"));
  for(var exclusion:rows(snapshot,Table.SENSITIVE_EXCLUSION))if(Objects.equals(snapshot.observation().get("exclusion_revision_id"),exclusion.string("revision_id"))){var locator=one(snapshot,Table.SOURCE_LOCATOR,exclusion.string("locator_id"));if(locator.string("kind").equals("TRANSCRIPT")){for(var segment:rows(snapshot,Table.TRANSCRIPT_SEGMENT))if(locator.string("transcript_revision_id").equals(segment.string("revision_id"))&&locator.string("segment_id").equals(segment.string("segment_id")))excluded.add(segment.string("body"));}else{var documents=rows(snapshot,Table.PARSED_DOCUMENT).stream().filter(r->Objects.equals(locator.nullableString("material_revision_id"),r.string("material_revision_id"))).map(r->r.string("id")).toList();for(var unit:rows(snapshot,Table.PARSED_UNIT))if(documents.contains(unit.string("document_id"))&&(locator.string("kind").equals("KNOWLEDGE_VERSION")||locator.nullableNumber("page_no")!=null&&Objects.equals(locator.nullableNumber("page_no"),unit.nullableNumber("page_no"))||locator.nullableNumber("paragraph_no")!=null&&Objects.equals(locator.nullableNumber("paragraph_no"),unit.nullableNumber("paragraph_no"))&&Objects.equals(locator.nullableString("section_path"),unit.nullableString("section_path"))))excluded.add(unit.string("body"));}}
  return ama.minutes.MinutesSensitiveContent.reintroduced(excluded,content);
 }
 private Map<String,Object> currentObservation(JdbcMinutesFactsReader.Snapshot snapshot){
  var value=new LinkedHashMap<>(observation(snapshot));if(!Boolean.TRUE.equals(value.get("needsGeneration")))return Collections.unmodifiableMap(value);
  var root=snapshot.observation();var current=freshnessInput(root,"revision");
  var completed=j.queryForList("SELECT i.transcript_confirmation_id,i.material_snapshot_id,i.template_revision_id,i.exclusion_revision_id,i.element_set_id,i.base_revision FROM generation_candidate c JOIN generation_input i ON i.id=c.input_id AND i.meeting_id=c.meeting_id JOIN durable_task t ON t.id=c.task_id AND t.input_id=i.id AND t.input_fingerprint=c.input_fingerprint AND t.output_id=c.id AND t.output_kind='GENERATION_CANDIDATE' WHERE c.meeting_id=? AND c.state='PENDING' AND i.scope='FULL' AND t.state='SUCCEEDED' AND c.base_revision=? AND t.business_version=c.base_revision AND t.cancel_epoch=? LIMIT 50",snapshot.graph().discovery().meeting(),root.get("revision"),root.get("cancel_epoch")).stream().map(row->new ama.minutes.MinutesGenerationFreshness.Completed(freshnessInput(row,"base_revision"),true,true,true)).toList();
  value.put("needsGeneration",ama.minutes.MinutesGenerationFreshness.needsPrompt(true,current,completed));return Collections.unmodifiableMap(value);
 }
 private static ama.minutes.MinutesGenerationFreshness.Input freshnessInput(Map<String,Object> row,String revision){return new ama.minutes.MinutesGenerationFreshness.Input((String)row.get("transcript_confirmation_id"),(String)row.get("material_snapshot_id"),(String)row.get("template_revision_id"),(String)row.get("exclusion_revision_id"),(String)row.get("element_set_id"),((Number)row.get(revision)).longValue());}
 private static Map<String,Object> observation(JdbcMinutesFactsReader.Snapshot s){var value=new LinkedHashMap<>(JdbcMinutesSettingsReceipts.observation(s.observation()));var root=s.observation();value.put("currentBodyId",root.get("minutes_revision_id"));value.put("currentSetId",root.get("element_set_id"));value.put("lifecycle",root.get("lifecycle"));value.put("templateRevisionId",root.get("template_revision_id"));value.put("exclusionRevisionId",root.get("exclusion_revision_id"));value.put("needsGeneration",((Number)root.get("needs_generation")).intValue()!=0);value.put("readOnlyReason",((Number)root.get("ever_published")).intValue()!=0?"PUBLISHED":null);return Collections.unmodifiableMap(value);}static Map<String,Object> map(Object... pairs){var result=new LinkedHashMap<String,Object>();for(int n=0;n<pairs.length;n+=2)result.put((String)pairs[n],pairs[n+1]);return Collections.unmodifiableMap(result);}
